BEGIN IMMEDIATE;
CREATE TABLE workflow_definitions(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL,definition_json TEXT NOT NULL CHECK(length(CAST(definition_json AS BLOB))<=1048576),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,digest),UNIQUE(organization_id,tenant_id,project_id,agent_uid,name,version));
CREATE TABLE workflow_instances(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,id TEXT NOT NULL,task_id TEXT NOT NULL,definition_digest TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,instance_json TEXT NOT NULL CHECK(length(CAST(instance_json AS BLOB))<=131072),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,id),UNIQUE(organization_id,tenant_id,project_id,agent_uid,task_id));
CREATE TABLE workflow_nodes(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,node_id TEXT NOT NULL,occurrence INTEGER NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL,node_json TEXT NOT NULL CHECK(length(CAST(node_json AS BLOB))<=16384),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,instance_id,node_id,occurrence));
CREATE TABLE workflow_leases(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,node_id TEXT NOT NULL,occurrence INTEGER NOT NULL,epoch INTEGER NOT NULL,executor_id TEXT NOT NULL,expires_at_ms INTEGER NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,instance_id,node_id,occurrence));
CREATE TABLE workflow_events(cursor INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,event_json TEXT NOT NULL CHECK(length(CAST(event_json AS BLOB))<=4096));
CREATE TABLE workflow_operations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,command_digest TEXT NOT NULL,result_json TEXT NOT NULL CHECK(length(CAST(result_json AS BLOB))<=1048576),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,actor_id,operation_id));
CREATE TRIGGER immutable_workflow_definition_update BEFORE UPDATE ON workflow_definitions BEGIN SELECT RAISE(ABORT,'immutable workflow definition'); END;
CREATE TRIGGER immutable_workflow_definition_delete BEFORE DELETE ON workflow_definitions BEGIN SELECT RAISE(ABORT,'immutable workflow definition'); END;
CREATE TRIGGER immutable_workflow_event_update BEFORE UPDATE ON workflow_events BEGIN SELECT RAISE(ABORT,'immutable workflow event'); END;
CREATE TRIGGER immutable_workflow_event_delete BEFORE DELETE ON workflow_events BEGIN SELECT RAISE(ABORT,'immutable workflow event'); END;
CREATE TRIGGER immutable_workflow_operation_update BEFORE UPDATE ON workflow_operations BEGIN SELECT RAISE(ABORT,'immutable workflow operation'); END;
CREATE TRIGGER immutable_workflow_operation_delete BEFORE DELETE ON workflow_operations BEGIN SELECT RAISE(ABORT,'immutable workflow operation'); END;
CREATE TRIGGER workflow_instance_identity BEFORE UPDATE ON workflow_instances WHEN NEW.definition_digest<>OLD.definition_digest OR NEW.task_id<>OLD.task_id OR NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.project_id<>OLD.project_id OR NEW.agent_uid<>OLD.agent_uid OR json_extract(NEW.instance_json,'$.input_digest')<>json_extract(OLD.instance_json,'$.input_digest') OR json_extract(NEW.instance_json,'$.creator')<>json_extract(OLD.instance_json,'$.creator') OR NEW.revision<=OLD.revision BEGIN SELECT RAISE(ABORT,'immutable workflow identity'); END;
CREATE TRIGGER workflow_node_identity BEFORE UPDATE ON workflow_nodes WHEN NEW.instance_id<>OLD.instance_id OR NEW.node_id<>OLD.node_id OR NEW.occurrence<>OLD.occurrence OR NEW.organization_id<>OLD.organization_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.project_id<>OLD.project_id OR NEW.agent_uid<>OLD.agent_uid OR json_extract(NEW.node_json,'$.input_digest')<>json_extract(OLD.node_json,'$.input_digest') OR json_extract(NEW.node_json,'$.lease_epoch')<json_extract(OLD.node_json,'$.lease_epoch') OR NEW.revision<=OLD.revision BEGIN SELECT RAISE(ABORT,'immutable workflow node input or stale fence'); END;
CREATE TRIGGER workflow_lease_epoch BEFORE UPDATE ON workflow_leases WHEN NEW.epoch<OLD.epoch OR (NEW.epoch=OLD.epoch AND NEW.executor_id<>OLD.executor_id) BEGIN SELECT RAISE(ABORT,'stale workflow lease'); END;
CREATE TRIGGER immutable_workflow_instance_delete BEFORE DELETE ON workflow_instances BEGIN SELECT RAISE(ABORT,'workflow retention requires evidence'); END;
CREATE TRIGGER immutable_workflow_node_delete BEFORE DELETE ON workflow_nodes BEGIN SELECT RAISE(ABORT,'workflow retention requires evidence'); END;
INSERT INTO principals VALUES('local-tenant','local-workflow-workload','workload',0);
INSERT INTO role_bindings VALUES('local-tenant','local-project','local-agent','local-workflow-workload','developer');
INSERT INTO schema_migrations VALUES(36,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
